  return{items:(await this.db.query<any>('SELECT id,name,period_type AS "periodType",start_time AS "startTime",end_time AS "endTime",duration_minutes AS "durationMinutes",sort_order AS "sortOrder",active,version FROM school_periods WHERE school_id=$1 AND active=true ORDER BY sort_order,name,id',[p.schoolId])).rows}
