  const assignments=all?(await this.db.query<any>('SELECT teacher_id AS "teacherId",academic_year_id AS "academicYearId",class_id AS "classId",section_id AS "sectionId",subject_id AS "subjectId" FROM teacher_assignments WHERE school_id=$1 AND active=true',[p.schoolId])).rows:assigned&&p.teacherId?(await this.db.query<any>('SELECT teacher_id AS "teacherId",academic_year_id AS "academicYearId",class_id AS "classId",section_id AS "sectionId",subject_id AS "subjectId" FROM teacher_assignments WHERE school_id=$1 AND active=true AND teacher_id=$2',[p.schoolId,p.teacherId])).rows:[];
